import * as THREE from 'three';

/**
 * Create a coffee mug as a THREE.Group containing:
 *  - `body`: a LatheGeometry profile (outer wall up, lip, inner wall down, inner floor)
 *  - `handle`: a half TorusGeometry whose inner edge touches the outer wall at mid height
 *
 * @param {object} opts
 * @param {number} [opts.radius=1]        outer radius of the cup
 * @param {number} [opts.height=2]        total height of the mug
 * @param {number} [opts.wallThickness=0.1]
 * @param {number} [opts.handleRadius=0.6] ring radius of the handle torus
 * @param {number} [opts.segments=64]     lathe/tubular segment count
 * @returns {THREE.Group}
 */
export function createMug({
  radius = 1,
  height = 2,
  wallThickness = 0.1,
  handleRadius = 0.6,
  segments = 64,
} = {}) {
  const group = new THREE.Group();
  group.name = 'mug';

  // --- Body: lathe profile (x = radial distance, y = height) ---
  const floorThickness = Math.min(wallThickness, height * 0.25);
  const innerRadius = Math.max(radius - wallThickness, radius * 1e-3);

  // Outer wall up -> lip -> inner wall down -> inner floor.
  const profile = [
    new THREE.Vector2(radius, 0),
    new THREE.Vector2(radius, height),
    new THREE.Vector2(innerRadius, height), // lip
    new THREE.Vector2(innerRadius, floorThickness),
    new THREE.Vector2(0, floorThickness),
  ];

  const bodyGeometry = new THREE.LatheGeometry(profile, segments);
  const body = new THREE.Mesh(bodyGeometry);
  body.name = 'body';
  group.add(body);

  // --- Handle: half torus in the XY plane, bulging toward +X ---
  const tubeRadius = handleRadius * 0.25;
  const radialSegments = Math.max(8, Math.floor(segments / 4));
  const handleGeometry = new THREE.TorusGeometry(
    handleRadius,
    tubeRadius,
    radialSegments,
    segments,
    Math.PI, // half torus
  );
  const handle = new THREE.Mesh(handleGeometry);
  handle.name = 'handle';
  // Default torus arc spans angles [0, PI] (upper semicircle); rotating by -PI/2
  // about Z puts the two open ends at (0, ±R) and the bulge toward +X.
  handle.rotation.z = -Math.PI / 2;
  // Center on the outer wall at mid height so the ends/inner edge sit flush
  // against the wall surface.
  handle.position.set(radius, height / 2, 0);
  group.add(handle);

  return group;
}

/**
 * Compute stats for a mug created by {@link createMug}.
 *
 * @param {THREE.Group} mug
 * @returns {{ bodyVertexCount: number, boundingBox: {
 *   min: {x: number, y: number, z: number},
 *   max: {x: number, y: number, z: number}
 * }}}
 */
export function mugStats(mug) {
  mug.updateMatrixWorld(true);

  const box = new THREE.Box3().setFromObject(mug);
  const body = mug.getObjectByName('body');

  return {
    bodyVertexCount: body.geometry.attributes.position.count,
    boundingBox: {
      min: { x: box.min.x, y: box.min.y, z: box.min.z },
      max: { x: box.max.x, y: box.max.y, z: box.max.z },
    },
  };
}

