import { test } from 'node:test';
import assert from 'node:assert/strict';

import { createMug, mugStats } from '../src/mug.js';

const base = { radius: 1, height: 2, wallThickness: 0.1, handleRadius: 0.6 };

const zExtent = (bb) => bb.max.z - bb.min.z;
const xExtent = (bb) => bb.max.x - bb.min.x;

test('bounding box height equals height within 1e-6', () => {
  for (const height of [1, 2, 3.5]) {
    const stats = mugStats(createMug({ ...base, height }));
    const measured = stats.boundingBox.max.y - stats.boundingBox.min.y;
    assert.ok(
      Math.abs(measured - height) < 1e-6,
      `expected height ${height}, got ${measured}`,
    );
  }
});

test('bounding box x-extent exceeds 2*radius because of the handle', () => {
  const stats = mugStats(createMug(base));
  const extent = xExtent(stats.boundingBox);
  assert.ok(
    extent > 2 * base.radius,
    `expected x-extent ${extent} > ${2 * base.radius}`,
  );
});

test('doubling radius doubles the bounding-box z-extent within 1%', () => {
  const small = mugStats(createMug(base));
  const big = mugStats(createMug({ ...base, radius: base.radius * 2 }));

  const z1 = zExtent(small.boundingBox);
  const z2 = zExtent(big.boundingBox);
  const relativeError = Math.abs(z2 - 2 * z1) / z1;

  assert.ok(
    relativeError < 0.01,
    `z-extent did not scale by 2: ${z1} -> ${z2} (${relativeError * 100}% off)`,
  );
});

test('bodyVertexCount changes when passing a segments option', () => {
  const few = mugStats(createMug({ ...base, segments: 24 })).bodyVertexCount;
  const many = mugStats(createMug({ ...base, segments: 96 })).bodyVertexCount;

  assert.notEqual(few, many);
  assert.ok(many > few, `expected more vertices with more segments: ${few} vs ${many}`);
});

